#!/usr/bin/env node
// A completed Civication day must never be silently regenerated by NextAction.
const assert = require("assert");
const fs = require("fs");
const path = require("path");
const vm = require("vm");

const source = fs.readFileSync(path.join(__dirname, "../js/Civication/ui/CivicationNextActionUI.js"), "utf8");

async function check(existingAction) {
  let startCalls = 0;
  let enqueueCalls = 0;
  const win = {
    addEventListener() {},
    CivicationState: { getActivePosition: () => ({ career_id: "naeringsliv", role_key: "tester", title: "Tester" }) },
    CivicationCalendar: { getPhase: () => "day_end" },
    CivicationDayProgression: { inspect: () => ({
      phase: "day_end", reason: "at_last_phase", openItemsInPhase: 0,
      pendingItem: null, nextQueuedItem: null, nextActionableItem: null
    }) },
    CivicationNextActionSelector: { getCurrent: () => existingAction },
    CivicationDailyMailBuilder: {
      inspect: () => ({ runtime: { role_scope: "tester", items: [
        { status: "answered", phase: "morning", event: { id: "old-mail" } }
      ] } }),
      startToday: async () => { startCalls += 1; return {}; },
      enqueueNext: async () => { enqueueCalls += 1; return {}; }
    }
  };
  vm.runInNewContext(source, { window: win, document: { readyState: "loading", addEventListener() {} }, console });
  const result = await win.CivicationNextActionUI.prepareNextActionSurface();
  assert.equal(result.stage, "day_end_no_rebuild");
  assert.equal(result.action?.id || null, existingAction?.id || null);
  assert.equal(startCalls, 0, "NextAction must not rebuild today's answered mail queue");
  assert.equal(enqueueCalls, 0, "NextAction must not enqueue earlier mails at day end");
}

(async () => {
  await check({ source: "day_phase_advance", id: "start_new_day:day_end", subject: "Start ny dag" });
  await check(null);
  console.log("Civication next-action day-end rebuild guard passed");
})().catch(error => { console.error(error); process.exitCode = 1; });
